public final class MainActivity extends Activity {
    private AppState state;private LinearLayout pageHost,imageList;private TextView status,deviceText,selectedText,avasFileText,lockFileText;private ProgressBar progress;
    private EditText password,forward,reverse,avasGain,lockGain;private CheckBox useAvasAudio,useCurves,enableSsh,clearRoot;private LinearLayout[] columns;private int nextCard;private final Button[] tabButtons=new Button[2];
    private File avasAudio,lockAudio;private int page;private String saveImageId="";private MediaPlayer player;
    private final int accent=Color.rgb(22,125,133),ink=Color.rgb(28,46,55),muted=Color.rgb(92,109,118);
    private final BroadcastReceiver updates=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){updateStatus();if(!state.busy.get())refreshLibrary();}};
    // Before API 33 the same-app signature permission protects this receiver.
    @android.annotation.SuppressLint("UnspecifiedRegisterReceiverFlag")
    @Override public void onCreate(Bundle bundle){super.onCreate(bundle);state=(AppState)getApplication();getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);if(Build.VERSION.SDK_INT>=33)registerReceiver(updates,new IntentFilter("com.kooo.evdashboard.STATUS"),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(updates,new IntentFilter("com.kooo.evdashboard.STATUS"),getPackageName()+".INTERNAL",null);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},90);render();}
    @Override protected void onResume(){super.onResume();try{state.storage();refreshLibrary();}catch(Exception ignored){}}
    @Override protected void onDestroy(){unregisterReceiver(updates);if(player!=null)player.release();super.onDestroy();}
    private float scale(){int width=getResources().getConfiguration().screenWidthDp;return width>=1800?1.6f:width>=1200?1.25f:1f;}
    private int dp(float v){return Math.round(getResources().getDisplayMetrics().density*v*scale());}
    private LinearLayout vertical(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size*scale());t.setTextColor(color);t.setPadding(0,dp(4),0,dp(5));return t;}
    private GradientDrawable background(int color,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(16));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
    private LinearLayout card(LinearLayout parent,String title){if(parent==pageHost&&columns!=null)parent=columns[(nextCard++)%2];LinearLayout c=vertical();c.setPadding(dp(18),dp(14),dp(18),dp(16));c.setBackground(background(Color.WHITE,Color.rgb(225,232,235)));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(10),0,dp(4));parent.addView(c,p);TextView h=text(title,19,ink);h.setTypeface(null,Typeface.BOLD);c.addView(h);return c;}
    private Button button(LinearLayout parent,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(15*scale());boolean primary=label.startsWith("应用")||label.startsWith("修改并")||label.startsWith("导出当前")||label.startsWith("检查权限");boolean caution=label.contains("写入当前")||label.startsWith("删除")||label.startsWith("临时");int fill=primary?accent:caution?Color.rgb(255,242,229):Color.rgb(234,244,244);b.setTextColor(primary?Color.WHITE:caution?Color.rgb(151,76,30):accent);b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(Color.rgb(202,224,224)),background(fill,0),null));b.setOnClickListener(v->{try{action.run();}catch(Exception e){error(e.getMessage());}});LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,dp(48));params.setMargins(0,dp(6),0,dp(2));parent.addView(b,params);return b;}
    private EditText field(LinearLayout parent,String label,String initial,int type){parent.addView(text(label,13,muted));EditText e=new EditText(this);e.setText(initial);e.setTextSize(16*scale());e.setTextColor(ink);e.setSingleLine(true);e.setInputType(type);parent.addView(e,new LinearLayout.LayoutParams(-1,dp(48)));return e;}
    private CheckBox check(LinearLayout parent,String label,boolean initial){CheckBox c=new CheckBox(this);c.setText(label);c.setTextColor(ink);c.setTextSize(15*scale());c.setButtonTintList(android.content.res.ColorStateList.valueOf(accent));c.setChecked(initial);parent.addView(c);return c;}
    private void render(){LinearLayout root=vertical();root.setPadding(dp(22),dp(16),dp(22),dp(12));root.setBackgroundColor(Color.rgb(243,245,247));TextView title=text("仪表工坊",29,ink);title.setTypeface(null,Typeface.BOLD);root.addView(title);root.addView(text("本地维护  /  原始备份保护  /  不上传车辆镜像",13,muted));LinearLayout tabs=new LinearLayout(this);root.addView(tabs);for(int i=0;i<2;i++){final int tab=i;Button b=new Button(this);tabButtons[i]=b;b.setText(i==0?"AVAS 与提示音":"仪表盘工坊");b.setTextSize(17*scale());b.setOnClickListener(v->{page=tab;showPage();});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(50),1);p.setMargins(i==0?0:dp(8),dp(8),0,dp(6));tabs.addView(b,p);}ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);pageHost=vertical();scroll.addView(pageHost);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setIndeterminate(true);root.addView(progress,new LinearLayout.LayoutParams(-1,dp(4)));status=text(state.status,13,muted);status.setMaxLines(4);root.addView(status);setContentView(root);showPage();updateStatus();}
    private void showPage(){pageHost.removeAllViews();for(int i=0;i<2;i++){tabButtons[i].setTextColor(i==page?Color.WHITE:accent);tabButtons[i].setBackground(background(i==page?accent:Color.WHITE,i==page?0:Color.rgb(212,227,230)));}imageList=null;deviceText=null;selectedText=null;columns=null;nextCard=0;if(getResources().getConfiguration().screenWidthDp>=900){LinearLayout row=new LinearLayout(this);columns=new LinearLayout[]{vertical(),vertical()};for(int i=0;i<2;i++){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);if(i==0)p.setMargins(0,0,dp(14),0);row.addView(columns[i],p);}pageHost.addView(row);}if(page==0)audioPage();else workshopPage();}
    @Override public void onConfigurationChanged(android.content.res.Configuration config){super.onConfigurationChanged(config);render();}
    private void updateStatus(){if(status!=null){status.setText(state.title+"\n"+state.status);status.setTextColor(state.failed?Color.rgb(166,57,35):muted);progress.setVisibility(state.busy.get()?View.VISIBLE:View.GONE);}}
    private void error(String s){new AlertDialog.Builder(this).setTitle("操作未开始").setMessage(s).setPositiveButton("知道了",null).show();}
    private void task(String label,AppState.Job job){try{state.submit(label,job);}catch(Exception e){error(e.getMessage());}}
    private void withStorage(String label,AppState.Job job){try{state.storage();task(label,job);}catch(Exception e){error(e.getMessage());}}
    private void confirm(String title,String message,Runnable yes){new AlertDialog.Builder(this).setTitle(title).setMessage(message).setNegativeButton("取消",null).setPositiveButton("确认",(d,w)->yes.run()).show();}
    private void parked(String title,String warning,Runnable yes){LinearLayout l=vertical();l.setPadding(dp(24),dp(12),dp(24),dp(8));l.addView(text(warning,15,ink));CheckBox c=check(l,"车辆已 P 挡驻车，期间不会驾驶",false);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(title).setView(l).setNegativeButton("取消",null).setPositiveButton("确认应用",null).create();dialog.setOnShowListener(v->{dialog.getButton(-1).setEnabled(false);c.setOnCheckedChangeListener((b,on)->dialog.getButton(-1).setEnabled(on));dialog.getButton(-1).setOnClickListener(b->{dialog.dismiss();yes.run();});});dialog.show();}
    private String pass(){return password==null?"":password.getText().toString();}
    private AudioEngine audio(){return new AudioEngine(this,state::report);}
    private SharedPreferences prefs(){return getSharedPreferences("settings",0);}
    private void audioPage(){
        LinearLayout intro=card(pageHost,"音效控制入口");intro.addView(text("通过 CP SSH 临时覆盖资源，不刷写固件。默认不修改任何声音。",14,muted));intro.addView(text("198.18.44.2 : 22  ·  root",16,ink));password=field(intro,"SSH 密码（留空即空密码；不保存）","",InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);
        button(intro,"检测并确认 SSH 主机指纹",()->task("检测 SSH 主机身份",()->{SshAccess.KeyOffer offer=SshAccess.inspectKey(this);runOnUiThread(()->confirm("确认 CP 主机指纹","请确认这是车内 CP。重启后密钥变化也需要重新确认。\n\n"+offer.fingerprint,()->{prefs().edit().putString("sshKnown",SshAccess.HOST+" "+offer.type+" "+offer.key).apply();state.report("已保存当前 CP 主机指纹，后续严格匹配。");}));}));
        button(intro,"连接并读取运行状态",()->{String p=pass();task("检测 CP SSH",()->state.report(audio().status(p)));});
        LinearLayout avas=card(pageHost,"AVAS · 行人提示音");avas.addView(text("实际声音和音量必须现场验收；配置检查不能替代声学及适用地区要求。",13,muted));useAvasAudio=check(avas,"使用自定义音频（最长 30 秒）",false);avasFileText=text("尚未选择音频",13,muted);avas.addView(avasFileText);
        button(avas,"选择 AVAS 音频",()->pick(12,"audio/*"));button(avas,"在本机试听所选音频",()->preview(avasAudio));useCurves=check(avas,"使用自定义音量 / 速度曲线",false);
        forward=field(avas,"正向速度点：0 / 5 / 10 / 15 / 20 / 25 / 30 km/h",prefs().getString("forward",""),InputType.TYPE_CLASS_TEXT);reverse=field(avas,"倒车曲线：7 个数值，逗号分隔",prefs().getString("reverse",""),InputType.TYPE_CLASS_TEXT);avasGain=field(avas,"曲线总音量（50–200%，默认 100）",Integer.toString(prefs().getInt("avasGain",100)),InputType.TYPE_CLASS_NUMBER);
        button(avas,"读取当前固件的原曲线",()->{String p=pass();task("读取 AVAS 曲线",()->{int[][] curves=audio().curves(p);runOnUiThread(()->{if(forward!=null){forward.setText(AudioEngine.join(curves[0]));reverse.setText(AudioEngine.join(curves[1]));useCurves.setChecked(true);}});state.report("已读取曲线，不采用其他车型的默认数值。尚未修改 CP。");});});
        button(avas,"应用 AVAS 设置",()->{try{String p=pass();File f=useAvasAudio.isChecked()?avasAudio:null;FilesEx.require(!useAvasAudio.isChecked()||f!=null,"请先选择音频");int[] a=useCurves.isChecked()?AudioEngine.parseOptional(forward.getText().toString()):null,b=useCurves.isChecked()?AudioEngine.parseOptional(reverse.getText().toString()):null;int gain=Integer.parseInt(avasGain.getText().toString());parked("应用 AVAS 设置","将短暂重启 AVAS 服务。不会写入原始资源；失败时尝试恢复上一覆盖。",()->task("应用 AVAS",()->audio().applyAvas(p,f,a,b,gain)));}catch(Exception e){error(e.getMessage());}});
        button(avas,"恢复 AVAS 默认资源并开启服务",()->{String p=pass();parked("恢复 AVAS 默认","仅移除仪表工坊自己的覆盖；检测到其他工具覆盖会停止。",()->task("恢复 AVAS",()->audio().restore(p,"avas")));});
        LinearLayout lock=card(pageHost,"锁车提示音");lockFileText=text("尚未选择音频",13,muted);lock.addView(lockFileText);button(lock,"选择锁车音频",()->pick(13,"audio/*"));button(lock,"在本机试听锁车音频",()->preview(lockAudio));lockGain=field(lock,"播放音量（25–200%，带峰值限制）",Integer.toString(prefs().getInt("lockGain",100)),InputType.TYPE_CLASS_NUMBER);
        button(lock,"应用锁车提示音",()->{try{FilesEx.require(lockAudio!=null,"请先选择音频");String p=pass();File f=lockAudio;int g=Integer.parseInt(lockGain.getText().toString());parked("应用锁车提示音","将短暂重启仪表音效服务，期间提示音可能不可用。",()->task("应用锁车声",()->audio().applyLock(p,f,g)));}catch(Exception e){error(e.getMessage());}});
        button(lock,"恢复默认锁车提示音",()->{String p=pass();parked("恢复锁车声","撤销本应用的锁车声覆盖并重启音效服务。",()->task("恢复锁车声",()->audio().restore(p,"lock")));});
        LinearLayout saved=card(pageHost,"已保存设置");CheckBox boot=check(saved,"开机尝试恢复已保存的 AVAS / 锁车音效",prefs().getBoolean("reapply",false));boot.setOnClickListener(v->{if(boot.isChecked())new AlertDialog.Builder(this).setTitle("启用开机音效恢复").setMessage("仅在能独立确认 P 挡、速度为零时执行；无法确认或 SSH 指纹变化时停止并提示。临时静音和 AVAS 停止不会开机重放。仅支持空密码自动连接。该自动功能需要实车验收。").setPositiveButton("启用",(d,w)->prefs().edit().putBoolean("reapply",true).apply()).setNegativeButton("取消",(d,w)->boot.setChecked(false)).setOnCancelListener(d->boot.setChecked(false)).show();else prefs().edit().putBoolean("reapply",false).apply();});
        button(saved,"手动重新应用已保存音效",()->{String p=pass();parked("重新应用音效","使用已保存音频和曲线，短暂重启对应服务。",()->task("重新应用音效",()->audio().reapplySaved(p)));});
        LinearLayout test=card(pageHost,"驻车测试 · 谨慎操作");test.addView(text("AVAS 与车辆提示音承担安全提醒作用。以下静音操作只用于驻车测试，不保存为开机设置，离开测试前必须恢复。",14,Color.rgb(154,79,28)));
        button(test,"临时停止 AVAS",()->{String p=pass();parked("临时停止行人提示音","行人将无法通过此声音判断车辆接近。确认仅在静止测试中使用。",()->confirm("再次确认停止 AVAS","测试结束后请立即开启 AVAS，禁止在道路行驶中使用静音状态。",()->task("驻车测试：停止 AVAS",()->audio().avasEnabled(p,false))));});
        button(test,"开启 AVAS 服务",()->{String p=pass();task("开启 AVAS",()->audio().avasEnabled(p,true));});
        button(test,"临时静音启用 / 退出提示（含巡航）",()->{String p=pass();parked("通用功能提示音测试","这两项资源除巡航外也可能被其他功能使用。仅限驻车测试，不改变巡航控制逻辑；不得在行驶中使用。",()->task("通用提示音驻车测试",()->audio().muteCruiseForTest(p)));});
        button(test,"恢复巡航提示音",()->{String p=pass();parked("恢复巡航提示音","移除本应用的两项覆盖并重启音效服务。",()->task("恢复巡航提示音",()->audio().restore(p,"cruise")));});
        restoreAudioLabels();
    }
    private void restoreAudioLabels(){String a=prefs().getString("draftAvas",prefs().getString("avasFile","")),l=prefs().getString("draftLock",prefs().getString("lockFile",""));if(!a.isEmpty()&&new File(a).isFile()){avasAudio=new File(a);avasFileText.setText("已选择本机 WAV："+avasAudio.getName());}if(!l.isEmpty()&&new File(l).isFile()){lockAudio=new File(l);lockFileText.setText("已选择本机 WAV："+lockAudio.getName());}}
    private void workshopPage(){
        LinearLayout device=card(pageHost,"设备与分区");deviceText=text(state.workshop!=null&&state.workshop.device!=null?state.workshop.device.summary():"尚未识别 CP 分区及当前槽位",15,ink);device.addView(deviceText);device.addView(text("镜像库：当前 Android 用户的 Documents/EVDashboard。卸载应用不会主动删除此目录；请另存重要备份到独立介质。",13,muted));
        button(device,"授权文件管理权限",()->startActivity(new Intent(Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION,Uri.parse("package:"+getPackageName()))));
        button(device,"检查权限并识别当前 CP 槽位",()->withStorage("识别 CP 分区",()->state.workshop.identify()));
        button(device,"导出当前分区（完整备份）",()->confirm("导出仪表分区","将只读复制当前 CP 分区，不修改车辆。完成校验后请确认是原始还是已修改镜像。请保持驻车、供电稳定且无 OTA。",()->withStorage("导出完整分区",()->{ImageRecord r=state.workshop.exportPartition();state.selected=r.id;runOnUiThread(()->classify(r));})));
        button(device,"导入本机 / U 盘镜像",()->pick(11,"application/octet-stream"));
        LinearLayout catalog=card(pageHost,"镜像存储列表");catalog.addView(text("原始、历史修改及导入镜像共用一个列表。选中不等于允许写入。",13,muted));imageList=vertical();catalog.addView(imageList);button(catalog,"刷新镜像列表",this::refreshLibrary);
        LinearLayout selected=card(pageHost,"当前选中镜像");selectedText=text("请先选择一份镜像",14,ink);selected.addView(selectedText);enableSsh=check(selected,"开启 SSH 开机监听（22 端口）",false);clearRoot=check(selected,"清除 root 密码，允许空密码登录",false);selected.addView(text("空密码会让能够访问此 SSH 入口的一方获得 root 权限。锁定账号或未知认证配置不会被静默改写。",13,muted));
        button(selected,"修改并生成新镜像",()->{boolean ssh=enableSsh.isChecked(),blank=clearRoot.isChecked();withStorage("生成镜像",()->{ImageRecord r=chosen();ImageRecord result=state.workshop.generate(r,ssh,blank);state.selected=result.id;state.report("新镜像生成并完整复核通过，原文件未改变；尚未刷写。");});});
        button(selected,"重新读取并校验所选镜像",()->withStorage("重新校验镜像",()->{ImageRecord r=chosen();state.workshop.verifyGenerated(r);state.report(r.message);}));
        button(selected,"确认镜像分类（仅待分类导出）",()->{try{classify(chosen());}catch(Exception e){error(e.getMessage());}});
        button(selected,"另存所选镜像到文件 / U 盘",()->{try{ImageRecord r=chosen();saveImageId=r.id;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"instrument-"+r.id+".img");startActivityForResult(i,14);}catch(Exception e){error(e.getMessage());}});
        button(selected,"删除所选镜像",this::deleteSelected);
        button(selected,"将所选镜像写入当前 CP 槽位",this::confirmFlash);
        LinearLayout audit=card(pageHost,"任务与恢复");audit.addView(text("生成检查、写后回读、启动验收是三个不同阶段。写入不自动重启，也不自动切槽。保留 A/B 不等于保证自动回退。",14,muted));button(audit,"检查未完成刷写任务（不会重新写入）",()->withStorage("核验未完成任务",()->state.workshop.recoverPending()));button(audit,"导出本次诊断记录",()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("text/plain").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"instrument-workshop-report.txt");startActivityForResult(i,15);});refreshLibrary();
        button(audit,"版本、数据说明与开源许可",this::licenses);
    }
    private void licenses(){String[] labels={"仪表工坊 0.1.0 测试版 · 数据与组件说明","EROFS GPL-2.0-or-later","JSch BSD","JZlib BSD","jBCrypt ISC"};String[] paths={"licenses/NOTICE.txt","licenses/erofs/GPL-2.0","licenses/jsch/LICENSE.txt","licenses/jsch/LICENSE.JZlib.txt","licenses/jsch/LICENSE.jBCrypt.txt"};new AlertDialog.Builder(this).setTitle("本机说明与开源许可").setItems(labels,(d,w)->{try(InputStream in=getAssets().open(paths[w])){ByteArrayOutputStream out=new ByteArrayOutputStream();FilesEx.transfer(in,out);new AlertDialog.Builder(this).setTitle(labels[w]).setMessage(new String(out.toByteArray(),java.nio.charset.StandardCharsets.UTF_8)).setPositiveButton("关闭",null).show();}catch(Exception e){error(e.getMessage());}}).show();}
    private ImageRecord chosen()throws Exception{state.storage();FilesEx.require(!state.selected.isEmpty(),"请先选择镜像");return state.library.get(state.selected);}
    private void refreshLibrary(){if(imageList==null||state.library==null)return;try{imageList.removeAllViews();List<ImageRecord> records=state.library.list();if(records.isEmpty())imageList.addView(text("暂无镜像。先导出分区或导入文件。",15,muted));for(ImageRecord r:records){TextView row=text((r.id.equals(state.selected)?"● ":"○ ")+r.name+"\n"+r.categoryLabel()+"  ·  "+(r.slot.isEmpty()?"未绑定槽位":r.slot)+"  ·  "+(r.bytes/(1024*1024))+" MiB\n"+(r.validated?"结构已校验":"待检查 / 检查未通过"),14,ink);row.setPadding(dp(10),dp(12),dp(10),dp(12));row.setBackground(background(r.id.equals(state.selected)?Color.rgb(227,244,239):Color.rgb(248,250,251),0));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(4),0,dp(4));imageList.addView(row,p);row.setFocusable(true);row.setOnClickListener(v->{state.selected=r.id;refreshLibrary();});}
            if(deviceText!=null&&state.workshop.device!=null)deviceText.setText(state.workshop.device.summary());if(!state.selected.isEmpty()){ImageRecord r=state.library.get(state.selected);selectedText.setText(r.name+"\n"+r.categoryLabel()+"\nSSH 配置："+r.socket+"  / root："+r.password+"\n允许空密码参数："+(r.blankAllowed?"是":"否 / 未知")+"\n固件基线："+(r.build.isEmpty()?"未知":r.build.substring(0,12))+"\nSHA-256："+r.sha+"\n"+r.message);}}
        catch(Exception e){if(selectedText!=null)selectedText.setText("镜像库读取失败："+e.getMessage());}}
    private void classify(ImageRecord r){if(!r.origin.equals("DEVICE")||!r.category.equals("UNCLASSIFIED")){error("仅未分类的分区导出需要确认；历史原始记录不能通过改分类绕过保护。");return;}new AlertDialog.Builder(this).setTitle("确认导出镜像类型").setMessage("分类由你确认，不代表软件已鉴定为原厂未修改。检测结果会独立保留。关闭弹窗则保持待分类。").setPositiveButton("仪表盘原始镜像",(d,w)->{try{boolean previous=false;for(ImageRecord other:state.library.list())if(other.original()&&other.group().equals(r.group()))previous=true;Runnable save=()->setCategory(r,"ORIGINAL");if(previous)confirm("原始镜像已保存过，是否再次保存","确认后保留本次新的独立文件和记录，不覆盖以前的原始镜像。取消则保持待分类。",save);else save.run();}catch(Exception e){error(e.getMessage());}}).setNegativeButton("已经修改过的镜像",(d,w)->setCategory(r,"MODIFIED")).show();}
    private void setCategory(ImageRecord r,String category){withStorage("确认镜像类型",()->{state.library.classify(r.id,category);state.report("分类已保存，原有镜像未覆盖。");});}
    private void deleteSelected(){try{FilesEx.require(!state.busy.get(),"任务进行中，暂不能删除镜像");ImageRecord r=chosen();confirm("删除镜像记录？",r.name+"\n文件将移入镜像库的 deleted 暂存目录，可人工恢复；不会触碰车辆分区。",()->{if(r.original())withStorage("检查剩余原始备份",()->{int remaining=state.library.remainingOriginals(r);FilesEx.require(remaining>0,"禁止删除最后一份有效原始镜像");runOnUiThread(()->confirm("再次确认删除原始镜像","已实际校验，同一车辆、槽位及固件基线仍有 "+remaining+" 份有效原始镜像未删除。\n确定删除所选记录？",()->performDelete(r.id,2)));});else performDelete(r.id,1);});}catch(Exception e){error(e.getMessage());}}
    private void performDelete(String id,int count){withStorage("删除镜像记录",()->{state.workshop.deleteImage(id,count);state.selected="";state.report("记录已移出列表，文件保留在 deleted 暂存目录，可人工恢复。");});}
    private void confirmFlash(){try{ImageRecord r=chosen();FilesEx.require(r.validated,"请先完成镜像校验");LinearLayout l=vertical();l.setPadding(dp(24),dp(12),dp(24),dp(12));
        l.addView(text("风险提示",18,Color.rgb(166,57,35)));l.addView(text("写入镜像可能破坏仪表盘系统，造成仪表故障、车机或远程连接不可用等严重后果，可能必须到售后自费维修。备份、校验通过及保留 A/B 槽位都不能保证恢复成功，也不能消除启动失败风险。请确认您能够承担这些风险。",15,ink));
        l.addView(text("操作要求",18,ink));l.addView(text("全程保持车辆通电和稳定供电，禁止断电、休眠、重启或 OTA 升级。请保持本应用在前台，尽量不要运行其他软件，尤其是高负载任务；不要强行停止应用。\n\n将写入重新识别出的当前 CP 槽位，不是 Android 槽位。完成全量回读前不要离开；本应用不会自动切槽或重启。",15,ink));
        CheckBox risk=check(l,"我已理解并愿意承担损坏及售后自费维修风险",false),parked=check(l,"车辆 P 挡驻车，期间不会驾驶",false),power=check(l,"全程保持稳定供电，不休眠、不重启",false),ota=check(l,"无 OTA / 其他刷写，保持本应用前台运行",false);
        CheckBox sameContent=check(l,"仅测试：允许与当前分区完全相同的镜像重写（无功能收益，仍有刷写风险）",false);
        ScrollView scroll=new ScrollView(this);scroll.addView(l);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("写入前必须确认 · "+r.name).setView(scroll).setNegativeButton("取消",null).setPositiveButton("核验后开始写入",null).create();dialog.setOnShowListener(v->{Button yes=dialog.getButton(-1);yes.setEnabled(false);CompoundButton.OnCheckedChangeListener change=(b,on)->yes.setEnabled(risk.isChecked()&&parked.isChecked()&&power.isChecked()&&ota.isChecked());risk.setOnCheckedChangeListener(change);parked.setOnCheckedChangeListener(change);power.setOnCheckedChangeListener(change);ota.setOnCheckedChangeListener(change);yes.setOnClickListener(b->{boolean test=sameContent.isChecked();dialog.dismiss();Runnable write=()->withStorage(test?"同内容受控重写测试":"受控写入 CP 分区",()->state.workshop.flash(r,true,true,true,true,test));if(test)confirm("再次确认同内容重写测试","这不是必要升级，不会带来功能变化。即使内容相同，重新写入仍可能因断电或硬件故障损坏仪表，可能需要售后自费维修。\n\n仅在候选与当前分区摘要完全相同且其他全部校验通过时执行；不跳过备份和全量回读。确定承担风险并测试？",write);else write.run();});});dialog.show();}catch(Exception e){error(e.getMessage());}}
    private void pick(int code,String mime){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType(mime).addCategory(Intent.CATEGORY_OPENABLE);if(code==11)i.setType("*/*");startActivityForResult(i,code);}
    private String displayName(Uri uri){try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst()){String name=c.getString(0);return name.length()>100?name.substring(0,100):name;}}catch(Exception ignored){}return "导入镜像";}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();
        if(request==11){String name=displayName(uri);withStorage("导入并检查镜像",()->{try(InputStream in=getContentResolver().openInputStream(uri)){ImageRecord r=state.workshop.importImage(in,name);state.selected=r.id;state.report("导入与结构检查完成，尚未证明与当前分区兼容。");}});}
        else if(request==12||request==13){task("解码并规范化音频",()->{byte[] wav=AudioImport.decode(this,uri,100);File dir=new File(getFilesDir(),"audio");FilesEx.require(dir.isDirectory()||dir.mkdir(),"无法创建音频目录");File file=new File(dir,UUID.randomUUID()+".wav");try(FileOutputStream out=new FileOutputStream(file)){out.write(wav);out.getFD().sync();}prefs().edit().putString(request==12?"draftAvas":"draftLock",file.toString()).apply();runOnUiThread(()->{if(request==12){avasAudio=file;if(avasFileText!=null){avasFileText.setText("已导入：48 kHz / 单声道 / PCM 16-bit");useAvasAudio.setChecked(true);}}else{lockAudio=file;if(lockFileText!=null)lockFileText.setText("已导入：48 kHz / 单声道 / PCM 16-bit");}});state.report("音频已保存到本机，尚未应用到 CP。");});}
        else if(request==14){String id=saveImageId;withStorage("另存镜像",()->{ImageRecord r=state.library.get(id);FilesEx.require(state.library.intact(r),"源镜像校验失败");try(InputStream in=new FileInputStream(state.library.file(r));OutputStream out=getContentResolver().openOutputStream(uri,"w")){FilesEx.require(out!=null,"无法写入所选位置");FilesEx.transfer(in,out);}try(InputStream verify=getContentResolver().openInputStream(uri)){java.security.MessageDigest md=java.security.MessageDigest.getInstance("SHA-256");byte[] buffer=new byte[1024*1024];int n;long count=0;while((n=verify.read(buffer))!=-1){md.update(buffer,0,n);count+=n;}FilesEx.require(count==r.bytes&&FilesEx.hex(md.digest()).equals(r.sha),"另存文件回读校验失败");}state.report("另存完成，目标文件已重新读取并核对摘要。");});}
        else if(request==15)task("导出诊断记录",()->{String report="仪表工坊 0.1.0\n"+state.title+"\n"+state.status+"\n";File log=new File(getFilesDir(),"last-task.log");if(log.isFile())report+=FilesEx.readText(log);try(OutputStream out=getContentResolver().openOutputStream(uri,"w")){out.write(report.getBytes(java.nio.charset.StandardCharsets.UTF_8));}state.report("诊断记录已导出，不包含密码或 shadow 密码字段。");});
    }
    private void preview(File f){try{FilesEx.require(f!=null&&f.isFile(),"请先选择音频");if(player!=null)player.release();player=new MediaPlayer();player.setDataSource(f.toString());player.prepare();player.start();new AlertDialog.Builder(this).setTitle("本机试听（不是 CP 播放）").setMessage("正在通过 Android 音频输出试听。实际车辆提示音需另行验收。").setPositiveButton("停止",(d,w)->{if(player!=null&&player.isPlaying())player.stop();}).setOnCancelListener(d->{if(player!=null&&player.isPlaying())player.stop();}).show();}catch(Exception e){error(e.getMessage());}}
}
